import { useEffect, useMemo, useState } from 'react';
import { ArrowLeft, Download, Pencil, RefreshCw } from 'lucide-react';
import { archiveExternalClientDocument, confirmExternalBiomarker, correctExternalBiomarker, createExternalClientInvitation, downloadExternalClientDocument, downloadExternalDietPlan, generateExternalDietPlan, getCurrentExternalClientInvitation, getExternalBiomarkerHistory, getExternalClient360, getExternalClientBiomarkers, getExternalDietPlan, processExternalClientReport, publishExternalDietPlan, regenerateExternalClientInvitation, rejectExternalBiomarker, revokeExternalClientInvitation, saveExternalDietPlan, updateExternalClient360, updateExternalClientDocument, uploadExternalClientDocument } from '../../lib/fiteatsyConsultantsApi';
import { validateExternalDietOption } from '../../lib/externalDietPlanPresentation.mjs';

const tabs = ['Overview', 'Health Profile', 'Nutrition', 'Diet Plan', 'Measurements', 'Reports', 'Biomarkers', 'Timeline'];
const groups = {
  'Health Profile': ['medicalHistory', 'conditionsSymptoms', 'allergiesFamilyHistory', 'medicationsSupplements', 'lifestyle', 'sleepStress', 'activityHydration', 'womensHealth'],
  Nutrition: ['nutrition', 'goals'],
  Measurements: ['measurements'],
};
const title = (value) => value.replace(/([A-Z])/g, ' $1').replace(/^./, (letter) => letter.toUpperCase());
const friendly = (value) => String(value).split('_').map((word)=>word ? `${word[0]}${word.slice(1).toLowerCase()}` : '').join(' ').replace(/^Non Vegetarian$/,'Non-Vegetarian').replace(/^One Two Week$/,'1–2 times/week').replace(/^5 Plus$/,'5+');
const show = (value) => Array.isArray(value) ? value.map(friendly).join(', ') || 'Not provided' : typeof value === 'object' && value !== null ? JSON.stringify(value) : value === null || value === undefined || value === '' ? 'Not provided' : /^[A-Z0-9_]+$/.test(String(value)) ? friendly(value) : String(value);

function Provenance({ value }) { return <span className="ml-2 rounded-full bg-slate-100 px-2 py-0.5 text-[10px] font-semibold text-slate-500">{value || 'Self-reported'}</span>; }
function SectionCard({ section, values, provenance, onEdit }) {
  return <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><h3 className="font-semibold">{title(section)}</h3><button onClick={() => onEdit(section, values)} className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 px-3 py-1.5 text-xs font-semibold"><Pencil size={13}/>Edit</button></div>{!values || Object.keys(values).length === 0 ? <p className="mt-4 text-sm text-slate-500">Not provided</p> : <dl className="mt-4 grid gap-3 sm:grid-cols-2">{Object.entries(values).map(([key, value]) => <div key={key} className="rounded-xl bg-slate-50 p-3"><dt className="text-xs font-medium text-slate-500">{title(key)}<Provenance value={provenance?.[key]?.sourceLabel || provenance?.sourceLabel}/></dt><dd className="mt-1 break-words text-sm font-medium">{show(value)}</dd></div>)}</dl>}</section>;
}

export function ExternalClient360({ client, practiceName, onBack, onStatus }) {
  const [data, setData] = useState(null); const [active, setActive] = useState('Overview'); const [error, setError] = useState(''); const [loading, setLoading] = useState(true); const [editing, setEditing] = useState(null);
  const [invitation, setInvitation] = useState(null); const [shareUrl, setShareUrl] = useState('');
  const [documentDialog, setDocumentDialog] = useState(null);
  const [biomarkers, setBiomarkers] = useState({ latest: [], pendingReviewCount: 0 }); const [history, setHistory] = useState(null); const [correction, setCorrection] = useState(null); const [processing, setProcessing] = useState('');
  const [dietPlan,setDietPlan]=useState({status:'NO_PLAN',plan:null});
  const [dietLoading,setDietLoading]=useState(false);
  const load = async () => { setLoading(true); setError(''); try { const result = await getExternalClient360(client.id); setData(result.client360); } catch (requestError) { setError(requestError.message || 'Unable to load Client 360.'); } finally { setLoading(false); } };
  useEffect(() => { void load(); getCurrentExternalClientInvitation(client.id).then((result) => setInvitation(result.invitation)).catch(() => setInvitation(null)); }, [client.id]);
  const overview = data?.overview;
  const edit = (section, values) => setEditing({ section, text: JSON.stringify(values || {}, null, 2) });
  const save = async () => { try { const values = JSON.parse(editing.text); const result = await updateExternalClient360(client.id, editing.section, values); setData(result.client360); setEditing(null); } catch (saveError) { setError(saveError.message || 'Unable to save changes.'); } };
  const issueInvitation = async () => { try { const result = await (invitation ? regenerateExternalClientInvitation(client.id) : createExternalClientInvitation(client.id)); setInvitation(result.invitation); setShareUrl(result.shareUrl); } catch (requestError) { setError(requestError.message || 'Unable to create invitation.'); } };
  const revokeInvitation = async () => { try { const result = await revokeExternalClientInvitation(client.id); setInvitation(result.invitation); setShareUrl(''); } catch (requestError) { setError(requestError.message || 'Unable to revoke invitation.'); } };
  const saveDocument = async (event) => { event.preventDefault(); try { if (documentDialog.document) await updateExternalClientDocument(client.id, documentDialog.document.id, documentDialog.values); else await uploadExternalClientDocument(client.id, { ...documentDialog.values, file: documentDialog.file }); setDocumentDialog(null); await load(); } catch (requestError) { setError(requestError.message || 'Unable to save document.'); } };
  const archiveDocument = async (documentId) => { try { await archiveExternalClientDocument(client.id, documentId); await load(); } catch (requestError) { setError(requestError.message || 'Unable to archive document.'); } };
  const loadBiomarkers = async () => { try { setBiomarkers(await getExternalClientBiomarkers(client.id)); } catch (requestError) { setError(requestError.message || 'Unable to load biomarker history.'); } };
  useEffect(() => { if (active === 'Biomarkers') void loadBiomarkers(); }, [active, client.id]);
  const loadDietPlan=async()=>{setDietLoading(true);setError('');try{setDietPlan(await getExternalDietPlan(client.id));}catch(requestError){setError(requestError.message||'Unable to load Diet Plan.');}finally{setDietLoading(false);}};
  useEffect(()=>{if(active==='Diet Plan')void loadDietPlan();},[active,client.id]);
  const processReport = async (documentId) => { setProcessing(documentId); setError(''); try { await processExternalClientReport(client.id, documentId); await Promise.all([load(), loadBiomarkers()]); setActive('Biomarkers'); } catch (requestError) { setError(requestError.message || 'Unable to process report.'); } finally { setProcessing(''); } };
  const review = async (observation, action) => { try { if (action === 'confirm') await confirmExternalBiomarker(client.id, observation.id); else if (action === 'reject') await rejectExternalBiomarker(client.id, observation.id); await loadBiomarkers(); } catch (requestError) { setError(requestError.message || 'Unable to review biomarker.'); } };
  const openHistory = async (item) => { try { const result = await getExternalBiomarkerHistory(client.id, item.canonicalBiomarkerId); setHistory({ name: item.name, rows: result.history }); } catch (requestError) { setError(requestError.message || 'Unable to load biomarker history.'); } };
  const saveCorrection = async (event) => { event.preventDefault(); try { await correctExternalBiomarker(client.id, correction.observation.id, { value: correction.value === '' ? null : Number(correction.value), unit: correction.unit || null, observationDate: correction.observationDate || null, reason: correction.reason }); setCorrection(null); await loadBiomarkers(); } catch (requestError) { setError(requestError.message || 'Unable to correct biomarker.'); } };
  const visibleSections = useMemo(() => groups[active] || [], [active]);
  return <section>
    <button onClick={onBack} className="mb-5 inline-flex items-center gap-2 text-sm font-semibold text-slate-600"><ArrowLeft size={17}/>Back to clients</button>
    {error && <div role="alert" className="mb-4 rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div>}
    {loading ? <div className="rounded-2xl bg-white p-12 text-center text-sm text-slate-500">Loading Client 360…</div> : data ? <>
      <header className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><div className="flex flex-col justify-between gap-5 md:flex-row"><div><p className="text-sm text-slate-500">Client 360</p><h2 className="mt-1 text-3xl font-semibold">{overview.name}</h2><p className="mt-2 text-sm text-slate-600">{[overview.age && `${overview.age} years`, overview.gender?.replaceAll('_', ' '), overview.primaryContact].filter(Boolean).join(' · ')}</p></div><div className="flex flex-wrap items-start gap-2">{overview.intakeStatus === 'COMPLETED' && <button onClick={()=>setActive('Diet Plan')} className="h-11 rounded-xl bg-blue-600 px-4 text-sm font-semibold text-white">Create Diet Plan</button>}<button onClick={load} aria-label="Refresh Client 360" className="rounded-xl border border-slate-200 p-2.5"><RefreshCw size={17}/></button><select value={overview.status} onChange={async (event) => { await onStatus(event.target.value); await load(); }} className="h-11 rounded-xl border border-slate-200 px-3">{['INVITED','INTAKE_STARTED','INTAKE_COMPLETED','ACTIVE','INACTIVE'].map((value) => <option key={value}>{value}</option>)}</select></div></div><div className="mt-6 grid gap-3 sm:grid-cols-4"><Summary label="Completeness" value={`${overview.profileCompleteness}%`}/><Summary label="Primary goal" value={overview.primaryGoal || 'Not provided'}/><Summary label="Diet preference" value={overview.dietPreference || 'Not provided'}/><Summary label="Documents" value={overview.documentCount}/></div>{overview.missingSections.length > 0 && <p className={`mt-4 text-xs ${overview.profileCompleteness===100?'text-slate-500':'text-amber-700'}`}>{overview.profileCompleteness===100?'Optional information not provided':'Missing required information'}: {overview.missingSections.map(title).join(', ')}</p>}</header>
      <nav className="my-5 flex gap-2 overflow-x-auto" aria-label="Client 360 sections">{tabs.map((tab) => <button key={tab} onClick={() => setActive(tab)} className={`whitespace-nowrap rounded-full px-4 py-2 text-sm font-semibold ${active === tab ? 'bg-slate-950 text-white' : 'bg-white text-slate-600'}`}>{tab}</button>)}</nav>
      {active === 'Overview' && <div className="grid gap-4 lg:grid-cols-2"><SectionCard section="basicProfile" values={Object.fromEntries(Object.entries(data.basicProfile).map(([key, item]) => [key, item.value]))} provenance={Object.fromEntries(Object.entries(data.basicProfile).map(([key, item]) => [key, item]))} onEdit={edit}/><div className="space-y-4"><section className="rounded-2xl border border-slate-200 bg-white p-5"><h3 className="font-semibold">Consent status</h3><p className="mt-3 text-sm">{data.consent.status}</p><p className="mt-1 text-xs text-slate-500">{data.consent.consentedAt ? new Date(data.consent.consentedAt).toLocaleString() : 'Consent has not been recorded.'}</p>{data.derived.bmi && <div className="mt-5 rounded-xl bg-slate-50 p-3"><p className="text-xs text-slate-500">BMI <Provenance value={data.derived.bmi.sourceLabel}/></p><p className="mt-1 text-lg font-semibold">{data.derived.bmi.value}</p></div>}</section><section className="rounded-2xl border border-slate-200 bg-white p-5"><h3 className="font-semibold">Health-profile invitation</h3><p className="mt-2 text-sm text-slate-500">{invitation ? invitation.status.replaceAll('_', ' ') : 'Not invited'}</p><div className="mt-4 flex flex-wrap gap-2"><button onClick={issueInvitation} className="rounded-xl bg-slate-950 px-4 py-2 text-sm font-semibold text-white">{invitation ? 'Regenerate' : 'Invite client'}</button>{invitation && ['PENDING','OPENED'].includes(invitation.status) && <button onClick={revokeInvitation} className="rounded-xl border border-red-200 px-4 py-2 text-sm font-semibold text-red-700">Revoke</button>}{shareUrl && <button onClick={() => navigator.clipboard.writeText(shareUrl)} className="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold">Copy secure link</button>}</div></section></div></div>}
      {visibleSections.length > 0 && <div className="grid gap-4 lg:grid-cols-2">{visibleSections.filter((section) => section !== 'womensHealth' || overview.gender === 'FEMALE').map((section) => <SectionCard key={section} section={section} values={data.sections[section]} provenance={data.provenance[section]} onEdit={edit}/>)}</div>}
      {active === 'Diet Plan' && <ExternalDietPlan state={dietPlan} loading={dietLoading} clientId={client.id} clientName={overview.name} practiceName={practiceName} onReload={loadDietPlan} onError={setError}/>}
      {active === 'Reports' && <div className="space-y-3"><div className="flex justify-end"><button onClick={() => setDocumentDialog({ values: { category: 'LAB_REPORT', displayName: '', documentDate: '', providerName: '', notes: '' }, file: null })} className="rounded-xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white">Upload report / document</button></div>{data.documents.length === 0 ? <Empty text="No reports or documents uploaded."/> : data.documents.map((document) => <div key={document.id} className="flex flex-col justify-between gap-3 rounded-2xl border border-slate-200 bg-white p-4 sm:flex-row sm:items-center"><div><p className="font-semibold">{document.name}</p><p className="mt-1 text-xs text-slate-500">{document.category.replaceAll('_',' ')} · {document.sourceLabel} · {document.mimeType} · {document.status}</p><p className="mt-1 text-xs text-slate-500">{document.documentDate || 'Document date not provided'} · Uploaded {new Date(document.uploadedAt).toLocaleString()}{document.providerName ? ` · ${document.providerName}` : ''}</p><p className="mt-1 text-xs font-semibold text-slate-600">Processing: {document.processingStatus.replaceAll('_',' ')}</p></div><div className="flex flex-wrap gap-2">{document.category === 'LAB_REPORT' && <button disabled={processing === document.id} onClick={() => processReport(document.id)} className="rounded-xl bg-blue-600 px-3 py-2 text-xs font-semibold text-white disabled:opacity-50">{processing === document.id ? 'Processing…' : document.processingStatus === 'NOT_REQUESTED' ? 'Process report' : 'Reprocess report'}</button>}<button onClick={() => downloadExternalClientDocument(client.id, document.id, document.name)} className="rounded-xl border border-slate-200 p-2.5" aria-label={`Download ${document.name}`}><Download size={17}/></button><button onClick={() => setDocumentDialog({ document, values: { category: document.category, displayName: document.name, documentDate: document.documentDate || '', providerName: document.providerName || '', notes: document.notes || '' } })} className="rounded-xl border border-slate-200 px-3 py-2 text-xs font-semibold">Edit</button><button onClick={() => archiveDocument(document.id)} className="rounded-xl border border-red-200 px-3 py-2 text-xs font-semibold text-red-700">Archive</button></div></div>)}</div>}
      {active === 'Biomarkers' && <BiomarkersPanel data={biomarkers} onHistory={openHistory} onConfirm={(item)=>review(item,'confirm')} onCorrect={(item)=>setCorrection({observation:item,value:item.value??'',unit:item.unit??'',observationDate:item.observationDate??'',reason:''})} onReject={(item)=>review(item,'reject')} onOpenReport={(item)=>downloadExternalClientDocument(client.id,item.documentId,`${item.name}-source-report`)}/>}
      {active === 'Timeline' && <div className="space-y-3">{data.timeline.length === 0 ? <Empty text="No operational history yet."/> : data.timeline.map((event, index) => <div key={`${event.occurredAt}-${index}`} className="rounded-2xl border border-slate-200 bg-white p-4"><p className="font-semibold">{title(event.type.toLowerCase())}</p><p className="mt-1 text-xs text-slate-500">{event.category} · {new Date(event.occurredAt).toLocaleString()}</p></div>)}</div>}
    </> : null}
    {editing && <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4"><div className="w-full max-w-xl rounded-2xl bg-white p-6"><h3 className="text-lg font-semibold">Edit {title(editing.section)}</h3><p className="mt-1 text-xs text-slate-500">Values are preserved as Consultant-entered history.</p><textarea aria-label="Section values" rows={14} value={editing.text} onChange={(event) => setEditing({ ...editing, text: event.target.value })} className="mt-4 w-full rounded-xl border border-slate-200 p-3 font-mono text-sm"/><div className="mt-4 flex justify-end gap-2"><button onClick={() => setEditing(null)} className="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold">Cancel</button><button onClick={save} className="rounded-xl bg-slate-950 px-4 py-2 text-sm font-semibold text-white">Save changes</button></div></div></div>}
    {documentDialog && <DocumentDialog state={documentDialog} setState={setDocumentDialog} onSave={saveDocument}/>}
    {history && <HistoryDialog state={history} onClose={()=>setHistory(null)}/>}
    {correction && <CorrectionDialog state={correction} setState={setCorrection} onSave={saveCorrection}/>}
  </section>;
}
function Summary({ label, value }) { return <div className="rounded-xl bg-slate-50 p-3"><p className="text-xs text-slate-500">{label}</p><p className="mt-1 truncate font-semibold">{show(value)}</p></div>; }
function Empty({ text }) { return <div className="rounded-2xl border border-dashed border-slate-300 bg-white p-10 text-center text-sm text-slate-500">{text}</div>; }
function ExternalDietPlan({state,loading,clientId,onReload,onError}) {
  const [targets,setTargets]=useState({dailyCalories:'',dailyProtein:''});
  const [busy,setBusy]=useState('');
  const plan=state?.plan;
  const version=plan?.version;
  const snapshot=version?.plan;
  const run=async(action)=>{setBusy(action);onError('');try{if(action==='generate')await generateExternalDietPlan(clientId,{dailyCalories:Number(targets.dailyCalories),dailyProtein:Number(targets.dailyProtein)});if(action==='save')await saveExternalDietPlan(clientId,snapshot.meals.flatMap(meal=>meal.options));if(action==='publish'){if(!window.confirm('Publish this exact Diet Plan version to the client?'))return;await publishExternalDietPlan(clientId);}await onReload();}catch(requestError){onError(requestError.message||'Unable to update Diet Plan.');}finally{setBusy('');}};
  const download=async()=>{setBusy('download');onError('');try{const{blob,filename}=await downloadExternalDietPlan(clientId);const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=filename;anchor.click();URL.revokeObjectURL(url);}catch(requestError){onError(requestError.message||'Unable to export Diet Plan.');}finally{setBusy('');}};
  if(loading)return <div className="rounded-2xl bg-white p-12 text-center text-sm text-slate-500">Loading Diet Plan…</div>;
  if(!plan)return <section className="rounded-2xl border border-slate-200 bg-white p-6"><h3 className="text-xl font-semibold">Create Diet Plan</h3><p className="mt-2 text-sm text-slate-500">Confirm the daily targets. Food options are generated from the Common Food catalogue using this client's completed intake, diet, restrictions and allergies.</p><div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold">Daily calories (kcal)<input type="number" min="800" max="6000" value={targets.dailyCalories} onChange={event=>setTargets({...targets,dailyCalories:event.target.value})} className="mt-2 w-full rounded-xl border border-slate-200 p-3"/></label><label className="text-sm font-semibold">Daily protein (g)<input type="number" min="20" max="400" value={targets.dailyProtein} onChange={event=>setTargets({...targets,dailyProtein:event.target.value})} className="mt-2 w-full rounded-xl border border-slate-200 p-3"/></label></div><button disabled={busy||!targets.dailyCalories||!targets.dailyProtein} onClick={()=>run('generate')} className="mt-5 rounded-xl bg-blue-600 px-5 py-3 text-sm font-semibold text-white disabled:opacity-40">{busy==='generate'?'Generating…':'Generate 7-meal Diet Plan'}</button></section>;
  return <div className="space-y-4"><section className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="text-xl font-semibold">Diet Plan · Version {version.number}</h3><p className="mt-1 text-sm text-slate-500">{plan.status.replaceAll('_',' ')} · {snapshot.dailyTargets.calories} kcal · {snapshot.dailyTargets.protein} g protein</p></div><div className="flex flex-wrap gap-2"><button disabled={busy} onClick={download} className="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold">{busy==='download'?'Preparing DOCX…':'Export DOCX'}</button>{plan.status==='DRAFT'&&<button disabled={busy} onClick={()=>run('save')} className="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold">Save Draft</button>}<button disabled={busy||plan.status==='PUBLISHED'} onClick={()=>run('publish')} className="rounded-xl bg-blue-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-40">{plan.status==='PUBLISHED'?'Published':busy==='publish'?'Publishing…':'Publish to Client'}</button></div></div><p className="mt-3 text-xs text-slate-500">External Consultant self-publish workflow. No Senior Consultant approval is required.</p></section>{snapshot.meals.map(meal=><section key={meal.mealHead} className="rounded-2xl border border-slate-200 bg-white p-5"><h4 className="font-semibold">{meal.mealHead.replaceAll('_',' ')}</h4><div className="mt-3 grid gap-3 lg:grid-cols-2">{meal.options.map((option,index)=>{const presented=validateExternalDietOption(option);return <article key={option.combinationId} className="rounded-xl bg-slate-50 p-4"><p className="text-xs font-semibold text-blue-700">Option {index+1}</p><p className="mt-1 font-semibold">{presented.title}</p>{presented.serving&&<p className="mt-1 text-xs text-slate-500">{presented.serving}</p>}<p className="mt-1 text-xs text-slate-500">{presented.nutrition.kcal===null?'—':Math.round(presented.nutrition.kcal)} kcal · P {presented.nutrition.protein===null?'—':presented.nutrition.protein.toFixed(1)} g · C {presented.nutrition.carbohydrate===null?'—':presented.nutrition.carbohydrate.toFixed(1)} g · F {presented.nutrition.fat===null?'—':presented.nutrition.fat.toFixed(1)} g</p></article>})}</div></section>)}</div>;
}
function BiomarkersPanel({data,onHistory,onConfirm,onCorrect,onReject,onOpenReport}) { return <div className="space-y-4"><div className="flex items-center justify-between"><div><h3 className="text-xl font-semibold">Biomarker history</h3><p className="text-sm text-slate-500">Latest result per biomarker. Open history for the complete timeline.</p></div>{data.pendingReviewCount>0&&<span className="rounded-full bg-amber-100 px-3 py-1 text-xs font-semibold text-amber-800">{data.pendingReviewCount} need review</span>}</div>{data.latest.length===0?<Empty text="No biomarkers detected. Process a lab report to begin."/>:<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{data.latest.map(item=><article key={item.canonicalBiomarkerId} className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-start justify-between gap-3"><div><h4 className="font-semibold">{item.name}</h4><p className="mt-1 text-2xl font-semibold">{show(item.value)} <span className="text-sm text-slate-500">{item.unit||''}</span></p></div><span className={`rounded-full px-2 py-1 text-[10px] font-semibold ${item.flag==='NORMAL'?'bg-emerald-100 text-emerald-700':'bg-amber-100 text-amber-800'}`}>{item.flag||'UNKNOWN'}</span></div><p className="mt-3 text-xs text-slate-500">{item.observationDate} · {item.reviewStatus.replaceAll('_',' ')}</p><p className="mt-1 text-xs text-slate-500">Reference: {item.referenceText||[item.referenceMin,item.referenceMax].filter(value=>value!==null).join(' – ')||'Not provided'}</p><div className="mt-4 flex flex-wrap gap-2"><button onClick={()=>onHistory(item)} className="rounded-lg border px-2.5 py-1.5 text-xs font-semibold">View history</button><button onClick={()=>onOpenReport(item)} className="rounded-lg border px-2.5 py-1.5 text-xs font-semibold">Source report</button>{item.reviewStatus==='REVIEW_REQUIRED'&&<><button onClick={()=>onConfirm(item)} className="rounded-lg bg-emerald-600 px-2.5 py-1.5 text-xs font-semibold text-white">Confirm</button><button onClick={()=>onCorrect(item)} className="rounded-lg border px-2.5 py-1.5 text-xs font-semibold">Correct</button><button onClick={()=>onReject(item)} className="rounded-lg border border-red-200 px-2.5 py-1.5 text-xs font-semibold text-red-700">Reject</button></>}</div></article>)}</div>}</div>; }
function HistoryDialog({state,onClose}) { return <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4"><section className="max-h-[85vh] w-full max-w-2xl overflow-auto rounded-2xl bg-white p-6"><div className="flex justify-between"><div><h3 className="text-lg font-semibold">{state.name} history</h3><p className="text-xs text-slate-500">All accepted observations, newest first.</p></div><button onClick={onClose} className="rounded-lg border px-3 py-1 text-sm">Close</button></div><div className="mt-4 space-y-2">{state.rows.map(row=><div key={row.id} className="grid grid-cols-3 gap-3 rounded-xl bg-slate-50 p-3 text-sm"><span>{row.observationDate}</span><strong>{show(row.value)} {row.unit||''}</strong><span className="text-right text-slate-500">{row.reviewStatus.replaceAll('_',' ')}</span></div>)}</div></section></div>; }
function CorrectionDialog({state,setState,onSave}) { const change=(key)=>(event)=>setState({...state,[key]:event.target.value}); return <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4"><form onSubmit={onSave} className="w-full max-w-md space-y-4 rounded-2xl bg-white p-6"><h3 className="text-lg font-semibold">Correct {state.observation.name}</h3><p className="text-xs text-slate-500">The extracted raw evidence is preserved. Your correction is stored as a reviewed layer.</p><input aria-label="Corrected value" type="number" step="any" value={state.value} onChange={change('value')} className="w-full rounded-xl border p-3"/><input aria-label="Corrected unit" value={state.unit} onChange={change('unit')} className="w-full rounded-xl border p-3"/><input aria-label="Observation date" type="date" value={state.observationDate} onChange={change('observationDate')} className="w-full rounded-xl border p-3"/><textarea required aria-label="Correction reason" placeholder="Reason for correction" value={state.reason} onChange={change('reason')} className="w-full rounded-xl border p-3"/><div className="flex justify-end gap-2"><button type="button" onClick={()=>setState(null)} className="rounded-xl border px-4 py-2">Cancel</button><button className="rounded-xl bg-slate-950 px-4 py-2 text-white">Save correction</button></div></form></div>; }
function DocumentDialog({state,setState,onSave}) { const change=(key)=>(event)=>setState({...state,values:{...state.values,[key]:event.target.value}}); return <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4"><form onSubmit={onSave} className="w-full max-w-lg space-y-4 rounded-2xl bg-white p-6"><h3 className="text-lg font-semibold">{state.document?'Edit document metadata':'Upload report / document'}</h3>{!state.document&&<input required type="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" onChange={(event)=>setState({...state,file:event.target.files?.[0]||null})} className="w-full text-sm"/>}<select required value={state.values.category} onChange={change('category')} className="w-full rounded-xl border border-slate-200 p-3">{['LAB_REPORT','PRESCRIPTION','MEDICAL_REPORT','IMAGING_REPORT','DISCHARGE_SUMMARY','OTHER_HEALTH_DOCUMENT'].map(value=><option key={value}>{value}</option>)}</select><input placeholder="Display name" value={state.values.displayName} onChange={change('displayName')} className="w-full rounded-xl border border-slate-200 p-3"/><input type="date" value={state.values.documentDate} onChange={change('documentDate')} className="w-full rounded-xl border border-slate-200 p-3"/><input placeholder="Provider or lab" value={state.values.providerName} onChange={change('providerName')} className="w-full rounded-xl border border-slate-200 p-3"/><textarea placeholder="Notes" value={state.values.notes} onChange={change('notes')} className="w-full rounded-xl border border-slate-200 p-3"/><div className="flex justify-end gap-2"><button type="button" onClick={()=>setState(null)} className="rounded-xl border px-4 py-2">Cancel</button><button disabled={!state.document&&!state.file} className="rounded-xl bg-slate-950 px-4 py-2 text-white disabled:opacity-40">{state.document?'Save metadata':'Upload'}</button></div></form></div>; }
